  struct ListNode *slow = head, *fast = head;
  while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) {
      struct ListNode *p = head;
      while (p != slow) {
        p = p->next;
        slow = slow->next;
      }
      return p;
    }
  }
  return NULL;
}

