}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode detectCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
      slow = slow.next;
      fast = fast.next.next;
      if (slow == fast) {
        ListNode p = head;
        while (p != slow) {
          p = p.next;
          slow = slow.next;
        }
        return p;
      }
    }
    return null;
  }
}

class Solution:
    def detectCycle(self, head: ListNode) -> ListNode:
        slow = fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow is fast:
                p = head
                while p is not slow:
                    p = p.next
                    slow = slow.next
                return p
        return None

impl Solution {
  pub fn detect_cycle(values: Vec<i32>, pos: i32) -> Option<i32> {
    let n = values.len() as i32;
    if pos < 0 {
      return None;
    }
    let next = |i: i32| -> i32 {
      if i == n - 1 {
        pos
      } else {
        i + 1
      }
    };
    let mut slow = 0i32;
    let mut fast = 0i32;
    loop {
      slow = next(slow);
      fast = next(next(fast));
      if slow == fast {
        break;
      }
    }
    let mut p = 0i32;
    while p != slow {
      p = next(p);
      slow = next(slow);
    }
    Some(values[p as usize])
  }
}

const detectCycle = (head: ListNode | null): ListNode | null => {
  let slow = head;
  let fast = head;
  while (fast && fast.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) {
      let p = head;
      while (p !== slow) {
        p = p!.next;
        slow = slow!.next;
      }
      return p;
    }
  }
  return null;
};
